export const t=(lang,key)=>(lang==='he'?he:en)[key]||en[key]||key;
export function validationMessages(config){const lang=config.language;if(lang!=='he')return null;const messages=[];for(const [key,label]of [['name','שם מלא'],['role','כותרת מקצועית'],['introduction','טקסט היכרות']])if(!config.profile[key].trim())messages.push(`יש למלא ${label}.`);for(const [key,field,label]of [['skills','name','קבוצת כישורים'],['experience','role','תפקיד'],['education','degree','השכלה'],['projects','name','פרויקט']])config[key].forEach((r,i)=>{if(!r[field].trim())messages.push(`יש לתת כותרת לרשומת ${label} ${i+1}, או להסיר אותה.`)});return messages;}
